export const LAUNDRY_MARKUP="<main id=\"laundry-operations-app\"><header><small>LAUNDRY OPERATIONS · INTAKE TO RETURN</small><h1>Easy Laundry operations workbench</h1><p>Source-backed service choices, assessed orders, actual work and recorded delivery.</p></header><div class=\"lo-notice\">A requested collection slot needs staff confirmation. Assess the items, agree the complete quote and record actual work before invoicing.</div><div class=\"lo-bar\"><button data-action=\"save-record\">Save complete record</button><button data-action=\"save-session\">Save working session</button><button data-action=\"open-record\">Open saved record</button><button data-action=\"save-html\">Save offline editor</button><button data-action=\"save-zip\">Download complete package</button><input id=\"lo-open-file\" type=\"file\" accept=\".json\" hidden></div><div class=\"lo-grid\"><label class=\"lo-field\"><span>Current operator</span><input id=\"lo-operator\" placeholder=\"Name for recorded changes\" autocomplete=\"off\"></label><label class=\"lo-field\"><span>Find a record or service</span><input id=\"lo-search\" type=\"search\" placeholder=\"Order reference, customer, service or address\"></label></div><p id=\"lo-status\" class=\"lo-status\" role=\"status\" aria-live=\"polite\"></p><div id=\"lo-summary\" class=\"lo-summary\"></div><nav id=\"lo-tabs\" class=\"lo-bar\" aria-label=\"Workbench sections\"></nav><section id=\"lo-content\"></section><footer class=\"lo-panel\"><p>Original source, operator choices, imported rows, pricing versions and history travel with the full saved record. The downloadable tracker is a neutral view; external payments and messages are recorded here after they actually occur.</p></footer></main>";
