 function loadValue(value){const v=value?.schema==='commons.laundry-workbench.v1'?value.record:value?.record&&value.ui?value.record:value;const next=E.validate(v);if(next.source_sha256!==record.source_sha256)throw Error('Choose a saved record for this complete original laundry source.');return {record:next,ui:value?.ui||null};}
 function actor(){const s=$('lo-operator').value.trim();if(!s)throw Error('Enter the actual operator name before recording a change.');return s}
 function list(name){if(name==='rates')return E.catalogue(record);if(name==='locations')return record.source.locations||[];if(name==='promotions')return record.source.promotions||[];if(name==='care-flags')return record.source.care_flags||[];if(name==='quote-lines')return (drafts.quote?.lines||[]).map(l=>({id:l.id,label:l.id+' · '+(l.rate_id||'service')}));if(name==='order-items'){const oid=drafts[formKey]?.order_id||selectedOrder;return (record.orders||[]).find(x=>x.id===oid)?.items||[];}return record[name]||[]}
 function options(f){if(Array.isArray(f.options))return f.options.map(x=>Array.isArray(x)?x:[x,x||'Choose']);return [['','Choose'],...list(f.options).map(x=>typeof x==='string'?[x,x]:[x.id,x.label||x.name||x.reference||x.id])]}
 function field(f,v,prefix=''){
  const path=prefix+f.key,label=esc(f.label),name=esc(path);
  if(f.type==='array')return '<fieldset class="lo-wide"><legend>'+label+'</legend>'+((v||[]).map((row,n)=>'<div class="lo-row"><div class="lo-grid">'+f.fields.map(x=>field(x,row[x.key],path+'.'+n+'.')).join('')+'</div><button type="button" data-action="remove-row" data-key="'+esc(f.key)+'" data-index="'+n+'">Remove row '+(n+1)+'</button></div>').join(''))+'<button type="button" data-action="add-row" data-key="'+esc(f.key)+'">Add row</button>'+(f.help?'<p class="lo-inline-help">'+esc(f.help)+'</p>':'')+'</fieldset>';
  if(f.type==='object')return '<fieldset class="lo-wide"><legend>'+label+'</legend><div class="lo-grid">'+f.fields.map(x=>field(x,(v||{})[x.key],path+'.')).join('')+'</div></fieldset>';
  let input='',value=v??'';if(f.type==='time'&&value){const d=new Date(value);if(Number.isFinite(d.getTime()))value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  if(f.type==='money')value=v===null||v===undefined||v===''?'':(Number(v)/100).toFixed(2);
  if(f.type==='select'||f.type==='multi')input='<select name="'+name+'"'+(f.type==='multi'?' multiple':'')+'>'+options(f).map(([key,title])=>'<option value="'+esc(key)+'"'+((f.type==='multi'?(v||[]).includes(key):String(v??'')===String(key))?' selected':'')+'>'+esc(title)+'</option>').join('')+'</select>';
  else if(f.type==='textarea')input='<textarea name="'+name+'" rows="'+(f.key==='source_text'?8:3)+'">'+esc(value)+'</textarea>';
  else if(f.type==='checkbox')input='<input type="checkbox" name="'+name+'"'+(v?' checked':'')+'>';
  else input='<input name="'+name+'" type="'+(f.type==='date'?'date':f.type==='email'?'email':f.type==='time'?'datetime-local':['number','integer','money'].includes(f.type)?'number':'text')+'"'+(f.type==='money'?' step="0.01" min="0"':f.type==='integer'?' step="1" min="0"':f.type==='number'?' step="any"':'')+' value="'+esc(value)+'"'+(f.placeholder?' placeholder="'+esc(f.placeholder)+'"':'')+'>';
  return '<label class="lo-field '+(f.type==='textarea'?'lo-wide':'')+'"><span>'+label+'</span>'+input+(f.help?'<small>'+esc(f.help)+'</small>':'')+'</label>';
 }
 function defaults(key){if(key==='mapping'&&E.transferFields){const f=schema.mapping.fields.find(x=>x.key==='fields');f.fields=E.transferFields('customers').map(x=>({key:x.key,label:x.label+(x.required?' (required)':''),type:'text'}));}const s=schema[key],x={};for(const f of s.fields){if(f.default!==undefined)x[f.key]=cp(f.default);else if(f.type==='array')x[f.key]=[];else if(f.type==='object')x[f.key]={};else if(f.type==='checkbox')x[f.key]=false;else if(f.type==='select'&&Array.isArray(f.options))x[f.key]=Array.isArray(f.options[0])?f.options[0][0]:f.options[0];else x[f.key]=f.type==='money'||f.type==='number'||f.type==='integer'?null:'';}if(key==='settings')return cp(record.settings);if('order_id'in x&&selectedOrder)x.order_id=selectedOrder;return x}
 function readField(form,f,prefix='',basis=drafts[formKey]||{}){
  const path=prefix+f.key;if(f.type==='array')return (basis[f.key]||[]).map((row,n)=>Object.fromEntries(f.fields.map(sub=>[sub.key,readField(form,sub,path+'.'+n+'.',row)])));
  if(f.type==='object')return Object.fromEntries(f.fields.map(sub=>[sub.key,readField(form,sub,path+'.',basis[f.key]||{})]));
  const el=form.querySelector('[name="'+path+'"]');if(!el)return basis[f.key]??'';
  if(f.type==='checkbox')return !!el.checked;if(f.type==='multi')return [...el.selectedOptions].map(o=>o.value);const v=el.value.trim();
  if(f.type==='money'){if(!v)return null;if(!/^\d+(?:\.\d{1,2})?$/.test(v))throw Error(f.label+' requires at most two decimal places.');const [a,b='']=v.split('.');return Number(a)*100+Number(b.padEnd(2,'0'));}
  if(f.type==='integer'||f.type==='number')return v===''?null:Number(v);
  if(f.type==='time')return v?new Date(v).toISOString():'';
  if(f.type==='textarea')return el.value;return v;
 }
 function collect(){const form=$('lo-form');if(!form||!schema[formKey])return drafts[formKey]||{};const old=drafts[formKey]||{};drafts[formKey]={...old,...Object.fromEntries(schema[formKey].fields.map(f=>[f.key,readField(form,f,'',old)]))};return drafts[formKey]}
 function filtered(rows){const q=$('lo-search').value.trim().toLowerCase();return q?rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q)):rows}
 function table(rows,cols,{form='',order=false}={}){if(!rows?.length)return '<p class="lo-muted">No actual records entered.</p>';return '<div class="lo-table"><table><thead><tr>'+cols.map(([,label])=>'<th>'+esc(label)+'</th>').join('')+(form||order?'<th>Open</th>':'')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+cols.map(([key])=>'<td>'+esc(asText(typeof key==='function'?key(row):row[key]))+'</td>').join('')+(form||order?'<td><button data-action="'+(order?'select-order':'edit')+'" data-form="'+esc(form)+'" data-id="'+esc(row.id)+'">Open</button></td>':'')+'</tr>').join('')+'</tbody></table></div>'}
 function issues(rows){return rows?.length?'<div class="lo-notice"><strong>Review before recording</strong><ul>'+rows.map(x=>'<li>'+esc(typeof x==='string'?x:x.text||x.message||JSON.stringify(x))+'</li>').join('')+'</ul></div>':''}
 function calculation(q){if(!q)return '';return '<div class="lo-panel"><h3>'+(q.complete?'Reviewed calculation':'Working price · decisions remain')+'</h3><p class="lo-amount">'+fmt(q.total_minor)+'</p>'+table(q.lines||[],[['id','Line'],['label','Service'],['quantity','Quantity'],[x=>fmt(x.unit_price_minor??x.rate_minor),'Rate'],[x=>fmt(x.amount_minor??x.total_minor??x.line_minor),'Line'],['note','Basis']])+table([{label:'Service charges',amount:q.service_subtotal_minor??q.subtotal_minor??q.service_minor},{label:'One collection/delivery charge',amount:q.delivery_minor},{label:'Selected discount',amount:q.discount_minor},{label:'Explicit minimum adjustment',amount:q.minimum_adjustment_minor},{label:'Tax',amount:q.tax_minor}].filter(x=>x.amount!==undefined),[['label','Calculation'],[x=>fmt(x.amount),'Amount']])+issues(q.issues)+'</div>'}
 function orderDetail(){if(!selectedOrder)return '';try{const v=E.orderView(record,selectedOrder);return '<div class="lo-panel"><h3>Selected order · '+esc(selectedOrder)+'</h3>'+table([v.order||v],[['status','State'],['customer_id','Customer'],['channel','Intake'],['location_id','Shop'],['promised_on','Promised'],['note','Notes']])+calculation(v.quotes?.find(q=>q.id===v.order?.quote_id)?.calculation||v.calculation||v.quote)+table(v.items||v.order?.items||[],[['id','Item/bag'],['label','Description'],['quantity','Quantity'],['care','Care'],['status','State']])+'<details><summary>Complete retained order view</summary><pre>'+esc(JSON.stringify(v,null,2))+'</pre></details></div>'}catch(e){return issues([e.message])}}
