 if(tab==='catalogue')return '<h3>Published and reviewed prices</h3>'+table(filtered(E.catalogue(record)),[['id','Service ID'],['label','Service'],['category','Category'],[x=>x.price_kind||x.pricing?.kind,'Price type'],[x=>fmt(x.selected_amount_minor),'Amount'],[x=>x.unit||x.pricing?.unit,'Unit'],['enabled','Enabled']],{form:'rate'})+'<h3>Original campaign observations</h3>'+table(record.source.promotions,[['id','Campaign'],['description','Published scope'],['percent','Percent'],['starts_on','Starts'],['ends_on','Ends'],['combination','Combination']])+'<h3>Source locations</h3>'+table(record.source.locations,[['id','Location'],['name','Name'],['role','Purpose'],['address','Address'],['opening','Published hours']]);
