 if(tab==='assessment')return '<h3>Assessment records</h3>'+table(record.assessments,[['id','Assessment'],['order_id','Order'],['received_on','Received'],['note','Assessment']],{form:'assessment'})+'<h3>Retained quotations</h3>'+table(record.quotes,[['id','Quote'],['order_id','Order'],['status','State'],['at','Prepared'],[x=>fmt(x.calculation?.total_minor??x.total_minor),'Total'],['approval','Actual approval']]);
