 if(tab==='routes')return '<h3>Drivers</h3>'+table(record.drivers,[['id','Driver'],['name','Name'],['phone','Phone'],['active','Active']],{form:'driver'})+'<h3>Driver routes</h3>'+table(record.routes,[['id','Route'],['driver_id','Driver'],['starts_at','Planned start'],[x=>x.departure?.actual_at,'Actual start'],['status','State'],['stops','Stop sequence']],{form:'route'})+'<h3>Actual handoffs</h3>'+table(record.handoffs,[['id','Handoff'],['order_id','Order'],['kind','Purpose'],['actual_at','Actual time'],['received_by','Recipient'],['reference','Reference']]);
