 if(tab==='complaints')return table(record.complaints,[['id','Complaint'],['order_id','Original order'],['reported_at','Reported'],['kind','Concern'],['description','Details'],['status','State'],['resolution','Actual resolution']],{form:'complaint'});
 if(tab==='imports')return '<h3>Saved mappings</h3>'+table(record.mappings,[['id','Mapping'],['entity','Register'],['fields','Source columns'],['note','Reason']],{form:'mapping'})+'<h3>Complete original imports</h3>'+table(record.imports,[['id','Import'],['filename','Original file'],['entity','Register'],[x=>(x.decisions||[]).filter(d=>d.action==='create').length,'Created'],[x=>(x.decisions||[]).filter(d=>d.action==='skip').length,'Skipped'],['source_sha256','Original digest']]);
 return '';
